// Conteúdo didático autoral do Equação. IDs estáveis independentes do currículo ENEM legado.
const n=v=>Number.isInteger(v)?String(v):String(Number(v.toFixed(5))).replace('.',',');
const Q=(statement,answer,explanation,wrong=null)=>({statement,answer:String(answer),explanation,wrong:wrong?.map(String)??[Number(answer)+1,Number(answer)-1,Number(answer)+2,Number(answer)*2+3].map(n)});
const L=(title,explanation,rule,card,cardAnswer,question,videoTerms=null,legacyIds=[])=>({title,explanation,rule,card:{question:card,answer:cardAnswer},question,videoTerms:videoTerms??title,legacyIds});
const fact=x=>x<=1?1:x*fact(x-1);
const groups=[
 ['Básico do básico','Construa a base para interpretar contas, transformar expressões e resolver problemas do dia a dia. Avance das operações para equações, proporções e juros.','basics',[
 L('As quatro operações básicas','Adição reúne quantidades; subtração compara ou retira. Multiplicação representa grupos iguais, e divisão reparte ou mede quantos grupos cabem.','Na divisão, o divisor não pode ser zero.','Qual operação desfaz uma multiplicação por um número diferente de zero?','A divisão pelo mesmo número.',k=>Q(`Uma papelaria recebeu ${k+3} caixas com 6 cadernos em cada uma e vendeu 5 cadernos. Quantos restaram?`,(k+3)*6-5,`Multiplique as caixas por 6 e subtraia os 5 vendidos: ${(k+3)*6} − 5 = ${(k+3)*6-5}.`),'operações fundamentais', ['math.m01.t05']),
 L('Expressões numéricas','Uma expressão combina operações. Resolva primeiro parênteses, depois potências e raízes, multiplicações e divisões, e por fim adições e subtrações.','Operações de mesma prioridade são feitas da esquerda para a direita.','Em 8 + 3 × 2, qual operação vem primeiro?','A multiplicação: 3 × 2. O resultado da expressão é 14.',k=>Q(`Uma compra é calculada por ${k+4} + 3 × (8 − 2). Qual é o total?`,k+22,`Parênteses: 8 − 2 = 6. Depois 3 × 6 = 18. Some ${k+4}: ${k+22}.`),'expressões numéricas',['math.m01.t06']),
 L('Frações','Uma fração indica partes iguais de uma unidade. Para somar frações, use denominadores iguais; para multiplicar, multiplique numeradores e denominadores.','a/b + c/b = (a + c)/b, com b ≠ 0.','Como somar frações de denominadores diferentes?','Encontre um denominador comum, escreva frações equivalentes e some os numeradores.',k=>Q(`Uma receita usa 1/2 de litro de leite por porção. Para ${2*(k+2)} porções, quantos litros são necessários?`,k+2,`Multiplique ${2*(k+2)} por 1/2: ${k+2} litros.`),'frações'),
 L('Operações com números decimais','Alinhe as vírgulas nas somas e subtrações. Na multiplicação, conte as casas decimais; na divisão, multiplique dividendo e divisor pela mesma potência de dez para retirar a vírgula do divisor.','0,5 = 5/10.','O que deve ficar alinhado ao somar números decimais?','As vírgulas e as casas de mesmo valor posicional.',k=>Q(`Cada metro de fita custa R$ 2,50. Quanto custam ${2*(k+2)} metros, em reais?`,5*(k+2),`${2*(k+2)} × 2,50 = ${5*(k+2)} reais.`),'números decimais',['math.m01.t04']),
 L('Dízimas periódicas','Uma dízima periódica repete infinitamente um bloco de algarismos. Ela representa um número racional e pode ser convertida em fração por uma equação.','Se x = 0,333…, então 10x − x = 3 e x = 1/3.','Qual fração representa 0,333…?','1/3.',k=>Q(`Uma calculadora mostra x = 0,${k+1}${k+1}${k+1}… com o mesmo algarismo se repetindo. Qual fração representa x?`,`${k+1}/9`,`Multiplique x por 10 e subtraia x: 9x = ${k+1}. Portanto x = ${k+1}/9.`,[`${k+1}/10`,`${k+1}/100`,`${k+2}/9`,`${k+1}/90`]),'dízima periódica'),
 L('Múltiplos e divisores','Múltiplos surgem ao multiplicar um número por inteiros. Um divisor positivo divide o número sem deixar resto.','Se a = b × c, b e c são divisores de a.','O que significa dizer que 4 é divisor de 20?','Que 20 ÷ 4 é inteiro: o resto é zero.',k=>Q(`Uma turma tem ${12+6*k} estudantes. A professora quer equipes de 3, sem sobras. Quantas equipes serão formadas?`,4+2*k,`${12+6*k} ÷ 3 = ${4+2*k}.`),'múltiplos e divisores',['math.m01.t07']),
 L('Critérios de divisibilidade','Critérios permitem testar divisões sem efetuar a conta inteira. Por 2, o último algarismo é par; por 3, a soma dos algarismos é múltipla de 3; por 5, termina em 0 ou 5.','Um número é divisível por 9 quando a soma de seus algarismos é múltipla de 9.','Como testar a divisibilidade por 3?','Some os algarismos e verifique se a soma é múltipla de 3.',k=>Q(`Uma escola numera seus materiais. Qual destes números é divisível por 9?`,String(18+9*k),`A soma dos algarismos de ${18+9*k} é múltipla de 9.`,[String(19+9*k),String(20+9*k),String(22+9*k),String(23+9*k)]),'critérios de divisibilidade',['math.m01.t08']),
 L('MMC e MDC','O mínimo múltiplo comum indica quando ciclos voltam a coincidir. O máximo divisor comum ajuda a repartir quantidades em grupos iguais tão grandes quanto possível.','Para inteiros positivos: MMC(a,b) × MDC(a,b) = a × b.','Qual medida ajuda a descobrir quando dois ciclos se encontram novamente?','O MMC dos períodos dos ciclos.',k=>Q(`Duas luzes piscam a cada ${2*(k+2)} e ${3*(k+2)} segundos. Se piscam juntas agora, em quantos segundos voltarão a coincidir?`,6*(k+2),`O MMC de ${2*(k+2)} e ${3*(k+2)} é ${6*(k+2)}.`),'MMC MDC',['math.m01.t10']),
 L('Potenciação','Uma potência representa multiplicações de fatores iguais. Ao multiplicar potências de mesma base, some os expoentes; ao elevar uma potência a outra, multiplique os expoentes.','aᵐ × aⁿ = aᵐ⁺ⁿ. Para a ≠ 0, a⁰ = 1.','Como multiplicar potências de mesma base?','Mantenha a base e some os expoentes.',k=>Q(`Um arquivo é duplicado a cada rodada. Partindo de 1 cópia, quantas existirão após ${k+3} rodadas?`,2**(k+3),`São ${k+3} fatores iguais a 2: 2^${k+3} = ${2**(k+3)}.`),'potenciação',['math.m04.t01']),
 L('Notação científica','A notação científica escreve números muito grandes ou pequenos de forma compacta: um coeficiente com módulo entre 1 e 10 multiplicado por uma potência de dez.','a × 10ⁿ, com 1 ≤ |a| < 10.','Qual é o intervalo do coeficiente positivo na notação científica?','1 ≤ a < 10.',k=>Q(`Um sensor registra ${k+2} × 10³ partículas. Quantas partículas isso representa?`,(k+2)*1000,`Multiplique ${k+2} por 1000.`),'notação científica',['math.m04.t03']),
 L('Transformação de unidades','Uma medida combina número e unidade. Comprimentos mudam por fatores de 10 entre prefixos vizinhos; áreas usam fatores ao quadrado e volumes, ao cubo.','1 m = 100 cm; 1 m² = 10 000 cm²; 1 L = 1000 mL.','Quantos centímetros quadrados há em 1 m²?','10 000 cm², pois 100 × 100 = 10 000.',k=>Q(`Uma garrafa tem capacidade de ${k+2} litros. Qual é a capacidade em mililitros?`,(k+2)*1000,`Cada litro equivale a 1000 mL: ${(k+2)*1000} mL.`),'conversão de unidades',['math.m05.t02']),
 L('Radiciação','Extrair uma raiz desfaz uma potência no domínio apropriado. A raiz quadrada principal de um número não negativo é sempre não negativa.','√(a²) = |a| para a real.','A expressão √(x²) vale x para todo número real?','Não. Vale |x|; por exemplo, √((-3)²) = 3.',k=>Q(`Um canteiro quadrado tem área de ${(k+4)**2} m². Quanto mede seu lado, em metros?`,k+4,`O lado é a raiz quadrada da área: √${(k+4)**2} = ${k+4}.`),'radiciação',['math.m04.t05']),
 L('Produtos notáveis','Alguns produtos algébricos aparecem com frequência e têm padrões úteis. No quadrado da soma, inclua o termo misto duas vezes.','(a+b)² = a² + 2ab + b²; (a+b)(a−b) = a²−b².','Qual termo costuma faltar ao desenvolver (a+b)²?','O termo 2ab.',k=>Q(`O lado de um jardim quadrado mede x + ${k+2} metros. Qual expressão representa sua área?`,`x² + ${2*(k+2)}x + ${(k+2)**2}`,`Use (x+a)² = x² + 2ax + a², com a = ${k+2}.`,[`x² + ${(k+2)**2}`,`x² + ${k+2}x + ${(k+2)**2}`,`2x + ${2*(k+2)}`,`x² − ${(k+2)**2}`]),'produtos notáveis',['math.m06.t03']),
 L('Fatoração','Fatorar transforma uma soma em produto. Procure fator comum, agrupamento, diferença de quadrados ou um trinômio quadrado perfeito.','ax + ay = a(x+y).','Como fatorar x² − 9?','Como diferença de quadrados: (x−3)(x+3).',k=>Q(`Ao simplificar um modelo, aparece x² − ${(k+2)**2}. Qual é sua forma fatorada?`,`(x−${k+2})(x+${k+2})`,'Use a diferença de quadrados: a²−b² = (a−b)(a+b).',[`(x−${k+2})²`,`(x+${k+2})²`,`x(x−${(k+2)**2})`,`(x−1)(x+${(k+2)**2})`]),'fatoração',['math.m06.t04']),
 L('Equações do primeiro grau','Uma equação afirma igualdade entre expressões. Faça a mesma operação nos dois lados para isolar a incógnita e confira a solução na expressão original.','ax + b = c → x = (c−b)/a, se a ≠ 0.','Por que somamos ou subtraímos o mesmo valor dos dois lados da equação?','Para preservar a igualdade.',k=>Q(`Uma corrida custa R$ 5 de taxa fixa mais R$ 3 por quilômetro. O total foi R$ ${5+3*(k+3)}. Quantos quilômetros foram percorridos?`,k+3,`5 + 3x = ${5+3*(k+3)}. Subtraia 5 e divida por 3: x = ${k+3}.`),'equação primeiro grau',['math.m06.t06']),
 L('Sistemas de equações','Um sistema pede valores que satisfaçam todas as equações ao mesmo tempo. Substituição e eliminação combinam as informações para encontrar esses valores.','x+y = s e x−y = d → 2x = s+d.','O que caracteriza uma solução de um sistema?','Ela satisfaz simultaneamente todas as equações do sistema.',k=>Q(`Uma loja vendeu x cadernos e y agendas. Foram ${2*k+10} itens e ${2*k+4} cadernos a mais que agendas. Quantas agendas foram vendidas?`,3,`x+y = ${2*k+10} e x−y = ${2*k+4}. Subtraindo: 2y = 6, então y = 3.`),'sistemas de equações',['math.m06.t08']),
 L('Equação do segundo grau','Uma equação quadrática tem termo de grau 2 com coeficiente não nulo. Suas raízes podem ser encontradas por fatoração ou pela fórmula de Bhaskara.','Δ = b²−4ac; x = (−b ± √Δ)/(2a).','O que indica Δ < 0 em uma equação quadrática com coeficientes reais?','Não há raízes reais.',k=>Q(`Ao modelar a área de um retângulo, surge x² − ${2*k+5}x + ${(k+2)*(k+3)} = 0. Qual é a menor raiz?`,k+2,`A expressão fatora em (x−${k+2})(x−${k+3}). As raízes são ${k+2} e ${k+3}.`),'equação segundo grau',['math.m07.t01']),
 L('Razão e proporção','Uma razão compara grandezas por uma divisão. Uma proporção afirma igualdade entre duas razões e exige atenção à ordem e às unidades.','a/b = c/d → ad = bc, com b,d ≠ 0.','O que é uma proporção?','Uma igualdade entre duas razões.',k=>Q(`Um suco usa 2 medidas de concentrado para 5 de água. Para ${2*(k+2)} medidas de concentrado, quantas de água são necessárias?`,5*(k+2),`A quantidade de concentrado foi multiplicada por ${k+2}; faça o mesmo com a água.`),'razão proporção',['math.m02.t01']),
 L('Regra de três simples','Relacione duas grandezas e decida se variam direta ou inversamente. Se uma dobra e a outra também dobra, a relação é direta; se a outra cai à metade, é inversa.','Na relação direta, y/x é constante; na inversa, xy é constante.','Como a grandeza dependente varia numa relação inversamente proporcional?','Quando uma aumenta por um fator, a outra diminui pelo mesmo fator.',k=>Q(`Três quilos de arroz custam R$ 18. Mantido o preço por quilo, quanto custam ${k+4} quilos?`,6*(k+4),`O quilo custa 18 ÷ 3 = 6 reais. Multiplique por ${k+4}.`),'regra de três simples',['math.m02.t03']),
 L('Regra de três composta','Problemas compostos envolvem três ou mais grandezas. Compare cada uma com a grandeza procurada, mantendo as outras constantes, antes de combinar os fatores.','Produção proporcional a trabalhadores × horas, se a produtividade individual for constante.','Qual cuidado vem antes de montar uma regra de três composta?','Identificar quais relações são diretas e quais são inversas.',k=>Q(`Duas máquinas produzem 20 peças em 1 hora. Com a mesma produtividade, quantas peças ${k+3} máquinas produzem em 2 horas?`,20*(k+3),`Cada máquina faz 10 peças por hora: ${k+3} × 2 × 10 = ${20*(k+3)}.`),'regra de três composta',['math.m02.t04']),
 L('Escalas','A escala compara uma medida no desenho com a medida real, usando a mesma unidade. Em áreas e volumes, o fator linear é elevado a 2 ou a 3.','Escala 1:N → distância real = distância no desenho × N.','Se as medidas lineares dobram, o que acontece com a área de figuras semelhantes?','A área fica quatro vezes maior.',k=>Q(`Em uma planta na escala 1:100, um corredor mede ${k+3} cm. Quantos metros ele mede na realidade?`,k+3,`${k+3} × 100 = ${(k+3)*100} cm, equivalentes a ${k+3} m.`),'escala',['math.m02.t06']),
 L('Porcentagem','Porcentagem significa uma parte em cada cem. Um aumento ou desconto é aplicado ao valor de referência; porcentagens sucessivas não são simplesmente somadas.','p% de V = (p/100)V.','Um desconto de 20% seguido de um aumento de 20% devolve o valor original?','Não. Os fatores são 0,8 e 1,2; o resultado é 96% do original.',k=>Q(`Uma mochila de R$ ${100*(k+2)} está com 10% de desconto. Qual é o preço final, em reais?`,90*(k+2),`Multiplique o preço por 0,90: ${90*(k+2)} reais.`),'porcentagem',['math.m03.t02']),
 L('Juros simples e compostos','Nos juros simples, os juros são calculados sempre sobre o capital inicial. Nos compostos, cada período incorpora os juros ao saldo para o cálculo seguinte.','Simples: M=C(1+it). Compostos: M=C(1+i)ᵗ.','Qual é a diferença entre juros simples e compostos?','Nos simples, a base é o capital inicial; nos compostos, é o saldo acumulado.',k=>Q(`R$ ${1000*(k+1)} foram aplicados a juros simples de 2% ao mês por 3 meses. Qual foi o juro total, em reais?`,60*(k+1),`J = C × i × t = ${1000*(k+1)} × 0,02 × 3 = ${60*(k+1)}.`),'juros simples compostos')]],
 ['Conjuntos','Organize elementos e compare grupos. A linguagem dos conjuntos ajuda a descrever números, possibilidades e domínios de funções.','basics',[
 L('Conceitos básicos de conjuntos','Um conjunto é uma coleção de elementos. Pertinência relaciona elemento e conjunto; inclusão compara conjuntos. A ordem não altera o conjunto e elementos repetidos contam uma única vez.','x ∈ A: x pertence a A. A ⊆ B: todo elemento de A está em B.','Qual a diferença entre ∈ e ⊆?','∈ indica pertinência de elemento; ⊆ indica inclusão entre conjuntos.',k=>Q(`Uma lista contém os códigos {1, 2, 2, ${k+4}}. Quantos elementos tem o conjunto desses códigos?`,3,'Elementos repetidos contam uma vez: 1, 2 e o último código.'),'conjuntos'),
 L('União e interseção de conjuntos','União reúne os elementos que aparecem em pelo menos um dos conjuntos. Interseção mantém apenas os elementos comuns. Ao contar uma união, subtraia a interseção para não contá-la duas vezes.','|A ∪ B| = |A| + |B| − |A ∩ B|.','O que representa A ∩ B?','Os elementos que pertencem simultaneamente a A e B.',k=>Q(`Em uma turma, ${10+k} alunos estudam inglês, ${8+k} espanhol e 4 os dois idiomas. Quantos estudam ao menos um desses idiomas?`,14+2*k,`${10+k} + ${8+k} − 4 = ${14+2*k}.`),'união interseção conjuntos'),
 L('Conjuntos numéricos','Naturais, inteiros, racionais e reais formam conjuntos encaixados. Irracionais não podem ser escritos como razão de inteiros e têm representação decimal infinita não periódica.','ℕ ⊂ ℤ ⊂ ℚ ⊂ ℝ; irracionais = ℝ \\ ℚ.','Todo número decimal infinito é irracional?','Não. Dízimas periódicas, como 0,333…, são racionais.',k=>Q(`Uma planilha contém estes valores. Qual deles é irracional?`,['√2','√3','√5','√7'][k], 'A raiz quadrada de um inteiro positivo que não é quadrado perfeito é irracional.',['0,5','−3','2/3','4']),'conjuntos numéricos')]],
 ['Funções','Entenda relações entre grandezas, leia gráficos e compare modelos. Explore funções polinomiais, modulares, exponenciais e logarítmicas.','functions',[
 L('Introdução às funções','Uma função associa cada elemento do domínio a exatamente uma imagem. A mesma imagem pode corresponder a entradas diferentes, mas uma entrada não pode ter duas saídas.','f: A → B. Para todo x ∈ A, existe uma única f(x) ∈ B.','Uma entrada pode ter duas saídas em uma função?','Não. Cada entrada do domínio tem exatamente uma imagem.',k=>Q(`Uma tabela usa a regra f(x)=2x+1 para calcular pontos. Quantos pontos correspondem à entrada x=${k+2}?`,2*k+5,`Substitua x: 2 × ${k+2} + 1 = ${2*k+5}.`),'introdução funções'),
 L('Funções lineares','Na convenção escolar, uma função linear é f(x)=ax. Seu gráfico passa pela origem e descreve proporcionalidade direta.','f(x)=ax e f(0)=0.','O gráfico de uma função linear passa por qual ponto?','Pela origem (0,0).',k=>Q(`Um pagamento proporcional às horas segue f(h)=${k+3}h. Qual é o pagamento para 4 horas?`,4*(k+3),`Multiplique o valor por hora por 4.`),'função linear'),
 L('Função afim','Uma função afim tem taxa de variação constante e pode ter valor inicial diferente de zero. No gráfico, o coeficiente angular indica a inclinação, e o termo constante indica a interseção com o eixo vertical.','f(x)=ax+b.','Em f(x)=ax+b, qual coeficiente representa o valor inicial f(0)?','b.',k=>Q(`Uma entrega cobra R$ ${k+4} fixos e R$ 2 por quilômetro. Quanto custa uma entrega de 5 km?`,k+14,`${k+4} + 2 × 5 = ${k+14}.`),'função afim'),
 L('Função do segundo grau','Uma função quadrática tem gráfico em forma de parábola. O sinal do coeficiente de x² define a concavidade, e o vértice localiza o extremo.','f(x)=ax²+bx+c, com a ≠ 0.','Se a > 0, a parábola tem concavidade para onde?','Para cima, com um ponto de mínimo.',k=>Q(`Um modelo de área usa A(x)=x²+${k+2}. Qual é A(3)?`,k+11,`3² + ${k+2} = ${k+11}.`),'função quadrática'),
 L('Máximos e mínimos da função','No caso quadrático, o vértice é o ponto de máximo ou mínimo. Se a<0, há máximo; se a>0, há mínimo. Verifique se a posição do vértice está no domínio do problema.','xᵥ=−b/(2a); yᵥ=f(xᵥ).','Uma parábola com a < 0 tem máximo ou mínimo?','Máximo.',k=>Q(`O lucro diário é modelado por L(x)=−(x−${k+3})²+20. Para qual valor de x o lucro é máximo?`,k+3,`O quadrado é mínimo, igual a zero, em x=${k+3}. Nesse ponto o lucro é 20.`),'máximo mínimo função'),
 L('Função composta e inversa','Compor funções significa aplicar uma após a outra. A inversa desfaz uma função quando a correspondência é bijetiva entre os conjuntos considerados.','(f ∘ g)(x)=f(g(x)).','Em f(g(x)), qual função é aplicada primeiro?','g, depois f.',k=>Q(`Um processamento usa g(x)=x+${k+2} e depois f(x)=2x. Qual é f(g(3))?`,2*(k+5),`g(3)=${k+5}; depois f(${k+5})=${2*(k+5)}.`),'função composta inversa'),
 L('Gráficos de funções','Um gráfico reúne pares (entrada, saída). Interseções, crescimento e extremos ajudam a interpretar o comportamento da função, mas a escala de cada eixo deve ser observada.','O ponto (x,y) pertence ao gráfico quando y=f(x).','Como verificar se um ponto pertence ao gráfico de f?','Substitua a coordenada x em f e compare o resultado com y.',k=>Q(`Um gráfico representa f(x)=3x. Qual é a coordenada vertical do ponto cuja coordenada horizontal é ${k+2}?`,3*(k+2),`y=f(${k+2})=3 × ${k+2}=${3*(k+2)}.`),'gráfico funções'),
 L('Inequações','Inequações comparam expressões por desigualdades. Somar o mesmo número preserva o sentido; multiplicar ou dividir por número negativo inverte o sinal da desigualdade.','Se a<b e c<0, então ac>bc.','Quando é preciso inverter o sinal de uma inequação?','Ao multiplicar ou dividir os dois lados por um número negativo.',k=>Q(`Um serviço custa 2x+4 reais e deve ficar abaixo de ${2*(k+5)+4} reais. Qual condição x deve satisfazer?`,`x < ${k+5}`,`2x+4 < ${2*(k+5)+4} → 2x < ${2*(k+5)} → x < ${k+5}.`,[`x > ${k+5}`,`x < ${k+7}`,`x ≥ ${k+5}`,`x = ${k+5}`]),'inequações'),
 L('Classificação de funções','Uma função é injetiva quando entradas distintas têm imagens distintas, sobrejetiva quando atinge todo o contradomínio, e bijetiva quando reúne as duas propriedades.','Uma função bijetiva admite inversa.','Que duas propriedades definem uma função bijetiva?','Ser injetiva e sobrejetiva.',k=>Q(`Considere f:ℝ→ℝ dada por f(x)=${k+2}x+1. Qual classificação está correta?`,'Bijetiva','O coeficiente angular é não nulo: a reta é injetiva e atinge todo número real.',['Constante','Não é função','Apenas sobrejetiva','Apenas injetiva']),'função injetora sobrejetora bijetora'),
 L('Módulo','O módulo de um número real representa sua distância até zero na reta. Distâncias são não negativas.','|x|=x se x≥0; |x|=−x se x<0.','O módulo de um número real pode ser negativo?','Não. Ele representa uma distância.',k=>Q(`A temperatura era −${k+4} °C. Qual é a distância desse valor até zero na reta numérica?`,k+4,`|−${k+4}|=${k+4}.`),'módulo valor absoluto'),
 L('Função modular','O módulo aplicado a uma expressão transforma partes negativas em positivas. O gráfico de |x| tem formato de V e pode sofrer translações.','f(x)=|x−a| tem mínimo zero em x=a.','Onde f(x)=|x−a| atinge o mínimo?','Em x=a.',k=>Q(`Um sensor calcula o desvio por f(x)=|x−${k+3}|. Qual é o desvio para x=1?`,k+2,`|1−${k+3}|=|−${k+2}|=${k+2}.`),'função modular'),
 L('Equações modulares','Para a≥0, a equação |u|=a significa u=a ou u=−a. Se a<0, não há solução real.','|x−b|=a → x=b+a ou x=b−a, quando a≥0.','Uma equação |x|=−2 tem solução real?','Não: o módulo nunca é negativo.',k=>Q(`Uma posição deve ficar a 2 unidades de ${k+5}. Qual é a menor solução de |x−${k+5}|=2?`,k+3,`x−${k+5}=±2. As posições são ${k+3} e ${k+7}.`),'equação modular'),
 L('Função exponencial','Uma função exponencial tem a variável no expoente. Com base maior que 1 ela cresce; com base entre 0 e 1 ela decresce.','f(x)=aˣ, com a>0 e a≠1.','Quando f(x)=aˣ é decrescente?','Quando 0<a<1.',k=>Q(`Uma cultura começa com 3 unidades e dobra a cada hora: P(t)=3×2ᵗ. Quantas unidades haverá após ${k+1} horas?`,3*2**(k+1),`P(${k+1})=3×2^${k+1}=${3*2**(k+1)}.`),'função exponencial'),
 L('Equação exponencial','Em muitas equações exponenciais, reescreva os dois lados com a mesma base. Para base positiva diferente de 1, potências iguais têm expoentes iguais.','aᵘ=aᵛ → u=v, se a>0 e a≠1.','O que fazer quando uma equação exponencial pode ser escrita com a mesma base?','Igualar os expoentes, respeitando as condições da base.',k=>Q(`Um processo cresce por fator 2 a cada etapa. Para atingir 2ˣ=${2**(k+3)}, qual deve ser x?`,k+3,`${2**(k+3)}=2^${k+3}; portanto x=${k+3}.`),'equação exponencial'),
 L('Logaritmo e propriedades','O logaritmo responde a qual expoente uma base deve ser elevada para produzir um número. O logaritmando deve ser positivo e a base positiva, diferente de 1.','logₐ(b)=c ⇔ aᶜ=b. logₐ(xy)=logₐ(x)+logₐ(y).','O logaritmo de uma soma é a soma dos logaritmos?','Não. A propriedade de soma de logaritmos vale para um produto no logaritmando.',k=>Q(`Um indicador usa log₂(${2**(k+2)}). Qual é esse valor?`,k+2,`2^${k+2}=${2**(k+2)}, então o logaritmo vale ${k+2}.`),'logaritmo propriedades'),
 L('Função logarítmica','A função logarítmica é inversa da exponencial de mesma base. Seu domínio real exige x>0, e seu gráfico passa por (1,0).','f(x)=logₐ(x), com x>0, a>0 e a≠1.','Qual é o domínio real de f(x)=logₐ(x)?','Os números reais positivos: x>0.',k=>Q(`Uma escala usa f(x)=log₁₀(x). Qual é f(${10**(k+1)})?`,k+1,`10^${k+1}=${10**(k+1)}; logo f=${k+1}.`),'função logarítmica')]],
 ['Geometria plana','Estude figuras no plano, suas medidas e relações. Use propriedades de ângulos, semelhança e áreas para justificar cada cálculo.','geometry',[
 L('Fundamentos de ângulos','Um ângulo mede a abertura entre duas semirretas de mesma origem. Ângulos complementares somam 90°; suplementares somam 180°.','Volta completa: 360°. Ângulo raso: 180°.','Quanto somam dois ângulos suplementares?','180°.',k=>Q(`Dois ângulos adjacentes formam uma linha reta. Um mede ${30+10*k}°. Quanto mede o outro?`,150-10*k,`A soma é 180°: 180−${30+10*k}=${150-10*k}.`),'ângulos',['math.m13.t01']),
 L('Triângulos','Um triângulo tem três lados e três ângulos internos. A soma dos ângulos internos é 180°, e cada lado deve ser menor que a soma dos outros dois.','α+β+γ=180°.','Qual é a soma dos ângulos internos de um triângulo plano?','180°.',k=>Q(`Um triângulo tem ângulos de 50° e ${40+10*k}°. Quanto mede o terceiro?`,90-10*k,`180−50−${40+10*k}=${90-10*k}.`),'triângulos',['math.m13.t03']),
 L('Congruência de triângulos','Triângulos congruentes têm forma e tamanho iguais. Critérios como LLL, LAL e ALA permitem demonstrar congruência sem medir todos os elementos.','LAL exige que o ângulo seja o compreendido entre os dois lados dados.','Qual é a diferença entre congruência e semelhança?','Congruência exige mesmo tamanho; semelhança exige mesma forma, com lados proporcionais.',k=>Q(`Dois triângulos têm lados ${k+3}, ${k+4} e ${k+5} cm em correspondência. Qual critério garante a congruência?`,'LLL','Os três lados correspondentes são iguais.',['AAA','Um único lado','Dois ângulos apenas','Só a área igual']),'congruência triângulos'),
 L('Pontos notáveis de um triângulo','Medianas encontram-se no baricentro; bissetrizes, no incentro; mediatrizes, no circuncentro; alturas, no ortocentro. Cada ponto tem uma construção e uma propriedade específica.','O baricentro divide cada mediana na razão 2:1, a partir do vértice.','Qual ponto é o encontro das três medianas?','O baricentro.',k=>Q(`Uma mediana mede ${3*(k+2)} cm. Qual é a distância do vértice ao baricentro nessa mediana?`,2*(k+2),`O trecho a partir do vértice mede 2/3 da mediana: ${2*(k+2)} cm.`),'pontos notáveis triângulo'),
 L('Quadriláteros','Quadriláteros têm quatro lados e soma dos ângulos internos igual a 360°. Retângulos, losangos e quadrados têm propriedades específicas; todo quadrado é também retângulo e losango.','Soma dos ângulos internos: 360°.','Todo retângulo é um quadrado?','Não. O quadrado também exige quatro lados iguais.',k=>Q(`Três ângulos de um quadrilátero medem 90°, 90° e ${60+10*k}°. Quanto mede o quarto?`,120-10*k,`360−90−90−${60+10*k}=${120-10*k}.`),'quadriláteros',['math.m14.t01']),
 L('Polígonos','Um polígono simples pode ser dividido em triângulos para calcular a soma de seus ângulos internos. Em um polígono regular, todos os lados e ângulos internos são iguais.','Soma dos ângulos internos: (n−2)×180°.','Qual é a soma dos ângulos externos de um polígono convexo, um por vértice?','360°.',k=>Q(`Uma praça tem formato de polígono convexo de ${k+5} lados. Qual é a soma dos ângulos internos, em graus?`,(k+3)*180,`(n−2)×180 = (${k+5}−2)×180 = ${(k+3)*180}.`),'polígonos'),
 L('Circunferência e círculo','A circunferência é a linha formada pelos pontos a uma distância fixa do centro. O círculo inclui essa linha e sua região interior. Não confunda comprimento com área.','Comprimento: C=2πr. Área: A=πr².','Qual a diferença entre circunferência e círculo?','Circunferência é a borda; círculo inclui a região interior.',k=>Q(`Uma pista circular tem raio ${k+3} m. Usando π=3, qual é o comprimento de uma volta?`,6*(k+3),`C=2πr=2×3×${k+3}=${6*(k+3)} m.`),'circunferência círculo',['math.m14.t05']),
 L('Semelhança de triângulos','Triângulos semelhantes têm ângulos correspondentes iguais e lados correspondentes proporcionais. A razão de áreas é o quadrado da razão entre lados.','Se a razão dos lados é k, a razão das áreas é k².','Se a razão dos lados é 3, qual é a razão entre as áreas?','9.',k=>Q(`Um triângulo foi ampliado por fator ${k+2}. Um lado original mede 4 cm. Quanto mede o lado correspondente?`,4*(k+2),`Multiplique o lado original pelo fator de ampliação.`),'semelhança triângulos',['math.m13.t05']),
 L('Relações métricas em quadriláteros','Neste item do roadmap, “triângulo quadrilátero” foi organizado como relações métricas em quadriláteros. Em um retângulo, a diagonal e dois lados formam um triângulo retângulo.','No retângulo: d²=a²+b².','Como encontrar a diagonal de um retângulo conhecendo seus lados?','Use Pitágoras: d=√(a²+b²).',k=>Q(`Uma placa retangular tem lados ${3*(k+1)} cm e ${4*(k+1)} cm. Quanto mede sua diagonal?`,5*(k+1),`Os lados são proporcionais a 3 e 4; a diagonal é 5 vezes ${k+1}.`),'diagonal retângulo'),
 L('Relações métricas na circunferência','Cordas que se cruzam no interior de uma circunferência têm produtos dos segmentos iguais. Relações análogas envolvem secantes e tangentes a partir de um ponto externo.','PA×PB=PC×PD para cordas AB e CD que se cruzam em P.','Qual relação vale para os segmentos de duas cordas que se cruzam dentro da circunferência?','O produto dos dois segmentos de uma corda iguala o da outra.',k=>Q(`Duas cordas se cruzam. Uma tem segmentos de 2 cm e ${6*(k+1)} cm; a outra, de 3 cm e x. Quanto vale x?`,4*(k+1),`2×${6*(k+1)}=3x. Logo x=${4*(k+1)}.`),'relações métricas circunferência'),
 L('Relações métricas em figuras semelhantes','Figuras semelhantes mantêm proporções entre comprimentos. Perímetros variam com o fator linear; áreas com seu quadrado; volumes com seu cubo.','Lados: k; áreas: k²; volumes: k³.','Se uma figura plana é ampliada por fator 2, sua área muda por qual fator?','Por fator 4.',k=>Q(`Uma figura de área 5 cm² foi ampliada com razão linear ${k+2}. Qual é a nova área?`,5*(k+2)**2,`Área nova = 5×${k+2}² = ${5*(k+2)**2} cm².`),'áreas figuras semelhantes'),
 L('Relações métricas no triângulo retângulo','Além de Pitágoras, a altura relativa à hipotenusa cria projeções que se relacionam aos catetos. Identifique a hipotenusa e as projeções antes de aplicar as fórmulas.','a²=b²+c²; h²=mn; b²=am; c²=an.','A hipotenusa fica oposta a qual ângulo?','Ao ângulo reto de 90°.',k=>Q(`Uma escada, o chão e a parede formam um triângulo retângulo com catetos ${3*(k+1)} m e ${4*(k+1)} m. Qual é o comprimento da escada?`,5*(k+1),`Use Pitágoras: √(${3*(k+1)}²+${4*(k+1)}²)=${5*(k+1)}.`),'relações métricas triângulo retângulo',['math.m13.t08'])]],
 ['Trigonometria','Conecte ângulos e comprimentos, avance para o ciclo trigonométrico e reconheça fenômenos periódicos.','trigonometry',[
 L('Conceitos básicos de trigonometria','Seno, cosseno e tangente relacionam ângulos a razões de comprimentos. No triângulo retângulo, essas razões dependem do ângulo, não do tamanho do triângulo.','sen θ=oposto/hipotenusa; cos θ=adjacente/hipotenusa.','O seno relaciona quais lados no triângulo retângulo?','Cateto oposto e hipotenusa.',k=>Q(`Em um triângulo retângulo, o cateto oposto mede ${3*(k+1)} e a hipotenusa ${5*(k+1)}. Qual é o seno do ângulo?`,'3/5','Divida o cateto oposto pela hipotenusa e simplifique.',['4/5','5/3','3/4','1/5']),'seno cosseno tangente',['math.m15.t01']),
 L('Trigonometria no triângulo retângulo','Escolha a razão trigonométrica que liga o lado conhecido ao procurado. Um desenho rotulado ajuda a distinguir cateto oposto, adjacente e hipotenusa.','tan θ=oposto/adjacente.','Qual razão usa os dois catetos e dispensa a hipotenusa?','A tangente.',k=>Q(`Uma rampa tem hipotenusa de ${2*(k+3)} m e inclinação de 30°. Sabendo que sen 30°=1/2, qual é a altura da rampa?`,k+3,`Altura = hipotenusa × sen 30° = ${2*(k+3)}×1/2 = ${k+3}.`),'trigonometria triângulo retângulo'),
 L('Lei dos senos e cossenos','Essas leis permitem resolver triângulos que não precisam ser retângulos. A lei dos senos relaciona lados aos ângulos opostos; a dos cossenos generaliza Pitágoras.','a/sen A=b/sen B=c/sen C; a²=b²+c²−2bc cos A.','Qual lei generaliza o teorema de Pitágoras?','A lei dos cossenos.',k=>Q(`Dois lados de um triângulo medem ${k+2} cm e formam 60°. Usando cos 60°=1/2, quanto mede o terceiro lado?`,k+2,`a²=2s²−2s²×1/2=s², então a=s=${k+2}.`),'lei senos cossenos'),
 L('Lei das áreas','Conhecendo dois lados e o ângulo entre eles, a área pode ser calculada com o seno desse ângulo. O ângulo usado precisa ser o compreendido entre os lados.','A=(ab sen θ)/2.','Qual ângulo deve ser usado em A=(ab sen θ)/2?','O ângulo compreendido entre os lados a e b.',k=>Q(`Um triângulo tem dois lados de 4 m e ${k+3} m, com ângulo de 30° entre eles. Usando sen 30°=1/2, qual é sua área?`,k+3,`A=(4×${k+3}×1/2)/2=${k+3} m².`),'área triângulo seno'),
 L('Ciclo trigonométrico','No círculo de raio 1, a coordenada horizontal corresponde ao cosseno e a vertical ao seno. Uma volta completa equivale a 2π radianos ou 360°.','180°=π rad.','A coordenada vertical de um ponto do ciclo representa seno ou cosseno?','Seno.',k=>Q(`Uma peça gira ${90*(k+1)}°. Qual é esse ângulo em radianos?`,['π/2','π','3π/2','2π'][k],`Multiplique o ângulo em graus por π/180.`,['π/3','π/4','5π/6','3π']),'ciclo trigonométrico',['math.m15.t05']),
 L('Função trigonométrica','Funções seno e cosseno descrevem oscilações. Em a sen(bx)+d, |a| controla a amplitude, d desloca o centro e o período é 2π/|b| para b≠0.','sen²x+cos²x=1.','Qual é o período de sen x, em radianos?','2π.',k=>Q(`A altura de uma onda segue h(t)=${k+2}sen(t)+10. Qual é sua amplitude?`,k+2,`A amplitude é o módulo do coeficiente do seno: ${k+2}.`),'função trigonométrica')]],
 ['Geometria espacial','Passe do plano ao espaço. Reconheça sólidos, posições e projeções, e diferencie área de superfície e volume.','geometry',[
 L('Conceitos de geometria espacial','Pontos, retas e planos ajudam a descrever o espaço. A área mede superfícies e usa unidades quadradas; volume mede espaço ocupado e usa unidades cúbicas.','1 m³ = 1000 L.','Em que tipo de unidade se mede volume?','Em unidades cúbicas, como cm³ e m³.',k=>Q(`Um cubo tem aresta ${k+2} cm. Qual é seu volume?`,(k+2)**3,`V=a³=${k+2}³=${(k+2)**3} cm³.`),'geometria espacial'),
 L('Projeções ortogonais','Uma projeção ortogonal representa um objeto sobre um plano por linhas perpendiculares a esse plano. Uma vista pode ocultar profundidade e não determina sempre o sólido de forma única.','As linhas projetantes são perpendiculares ao plano de projeção.','Uma única projeção sempre identifica um sólido?','Não. Sólidos diferentes podem ter a mesma projeção.',k=>Q(`Um bloco retangular de base ${k+3} m por 2 m é visto de cima, perpendicularmente à base. Qual é a área da projeção?`,2*(k+3),`A vista superior é o retângulo da base: ${k+3}×2=${2*(k+3)}.`),'projeções ortogonais'),
 L('Poliedros e prismas','Poliedros têm faces poligonais planas. Um prisma tem bases congruentes e paralelas, e seu volume é a área da base multiplicada pela altura perpendicular.','V_prisma=A_base×h.','Qual é a fórmula do volume de um prisma?','Área da base multiplicada pela altura.',k=>Q(`Um reservatório em forma de prisma tem base de área ${k+4} m² e altura 3 m. Qual é o volume?`,3*(k+4),`V=A_base×h=${k+4}×3=${3*(k+4)}.`),'prismas poliedros'),
 L('Pirâmides','Uma pirâmide tem uma base poligonal e faces laterais triangulares que chegam a um vértice comum. Para mesma base e altura, seu volume é um terço do volume do prisma.','V_pirâmide=A_base×h/3.','Que fração do volume de um prisma tem uma pirâmide de mesma base e altura?','Um terço.',k=>Q(`Uma pirâmide tem base de área ${3*(k+2)} m² e altura 4 m. Qual é o volume?`,4*(k+2),`V=${3*(k+2)}×4/3=${4*(k+2)} m³.`),'pirâmides'),
 L('Cilindros e cones','Cilindros e cones têm bases circulares. O cilindro ocupa área da base vezes altura; o cone, um terço disso. A altura é perpendicular à base e pode ser diferente da geratriz.','V_cilindro=πr²h; V_cone=πr²h/3.','Cone e cilindro de mesma base e altura têm volumes iguais?','Não. O cone tem um terço do volume do cilindro.',k=>Q(`Uma lata cilíndrica tem raio 2 cm e altura ${k+3} cm. Usando π=3, qual é seu volume?`,12*(k+3),`V=3×2²×${k+3}=${12*(k+3)} cm³.`),'cilindro cone'),
 L('Esfera','Uma esfera reúne os pontos do espaço a uma distância menor ou igual ao raio em relação ao centro. A superfície esférica é sua borda.','Área=4πr²; volume=4πr³/3.','Se o raio de uma esfera dobra, por qual fator muda o volume?','Por 8, pois o volume depende de r³.',k=>Q(`Uma bola esférica tem raio ${k+1} cm. Usando π=3, qual é seu volume?`,4*(k+1)**3,`V=4×3×${k+1}³/3=${4*(k+1)**3} cm³.`),'esfera'),
 L('Inscrição e circunscrição','Um sólido inscrito fica dentro de outro com pontos de contato na borda. Uma figura circunscrita envolve a outra. Use simetrias e diagonais para encontrar as medidas de contato.','Num cubo de aresta a, a esfera inscrita tem raio a/2.','Qual é o diâmetro da esfera inscrita em um cubo?','A medida da aresta do cubo.',k=>Q(`Uma esfera é inscrita em um cubo de aresta ${2*(k+2)} cm. Qual é o raio da esfera?`,k+2,`O diâmetro é a aresta; o raio vale a metade: ${k+2}.`),'sólidos inscritos circunscritos'),
 L('Geometria de posição','No espaço, duas retas podem ser concorrentes, paralelas ou reversas. Retas reversas não se cruzam e não pertencem ao mesmo plano.','Retas reversas são não coplanares.','O que distingue retas reversas de retas paralelas?','Retas reversas não são coplanares; as paralelas são.',k=>Q(`Num modelo espacial, duas retas ${k+1===1?'r e s':'a e b'} não se encontram e não pertencem ao mesmo plano. Como são classificadas?`,'Reversas','Retas não coplanares e sem interseção são reversas.',['Paralelas','Coincidentes','Concorrentes','Perpendiculares concorrentes']),'geometria posição')]],
 ['Progressões','Reconheça padrões numéricos, descreva termos e calcule somas. Diferencie crescimento por adição constante e por multiplicação constante.','progressions',[
 L('Introdução às sequências numéricas','Uma sequência é uma lista ordenada de termos, geralmente indexada pelos naturais. Uma regra explícita calcula o termo diretamente; uma recorrência usa termos anteriores.','aₙ representa o termo na posição n.','Qual a diferença entre regra explícita e recorrência?','A explícita dá o termo pela posição; a recorrência relaciona termos sucessivos.',k=>Q(`As fileiras de um auditório seguem a regra aₙ=2n+${k+1}. Quantos lugares tem a 5ª fileira?`,k+11,`a₅=2×5+${k+1}=${k+11}.`),'sequências numéricas'),
 L('Progressão aritmética','Numa PA, a diferença entre termos consecutivos é constante. A soma de termos pode ser obtida pela média do primeiro e do último, multiplicada pela quantidade.','aₙ=a₁+(n−1)r; Sₙ=n(a₁+aₙ)/2.','O que permanece constante em uma PA?','A diferença entre dois termos consecutivos, chamada razão.',k=>Q(`Um atleta corre ${k+2} km no primeiro dia e aumenta 2 km por dia. Quantos quilômetros correrá no 4º dia?`,k+8,`a₄=a₁+3r=${k+2}+3×2=${k+8}.`),'progressão aritmética'),
 L('Progressão geométrica','Numa PG, cada termo é o anterior multiplicado por uma razão constante. Crescimentos percentuais repetidos são modelados por esse padrão.','aₙ=a₁qⁿ⁻¹.','O que permanece constante em uma PG com termos não nulos?','O quociente entre termos consecutivos, chamado razão.',k=>Q(`Uma sequência de dobraduras começa com ${k+1} camadas e dobra a quantidade a cada etapa. Quantas camadas há no 4º termo?`,8*(k+1),`a₄=a₁×2³=${8*(k+1)}.`),'progressão geométrica')]],
 ['Análise combinatória e probabilidade','Conte possibilidades sem listar todos os casos. Depois use as contagens para calcular probabilidades com as hipóteses adequadas.','combinatorics',[
 L('Noções básicas de combinatória','A contagem combina decisões em etapas. Use o princípio multiplicativo para escolhas sucessivas e o aditivo para alternativas mutuamente exclusivas.','Se uma escolha tem a opções e a seguinte b, há a×b pares.','Quando usamos o princípio multiplicativo?','Ao combinar escolhas sucessivas, com as quantidades de opções de cada etapa.',k=>Q(`Uma lanchonete oferece ${k+3} sanduíches e 4 bebidas. Quantos combos com um de cada podem ser montados?`,4*(k+3),`Multiplique as opções das duas etapas: ${k+3}×4.`),'princípio fundamental contagem'),
 L('Fatorial','O fatorial de um inteiro não negativo é o produto dos inteiros positivos até ele. Por convenção, 0! = 1, o que mantém coerentes as fórmulas de contagem.','n!=n(n−1)…1; 0!=1.','Quanto vale 0!?','1.',k=>Q(`Uma fórmula de organização usa ${k+3}!. Qual é seu valor?`,fact(k+3),`Multiplique os inteiros de 1 até ${k+3}: ${fact(k+3)}.`),'fatorial'),
 L('Permutações simples','Permutar significa ordenar todos os elementos distintos de um conjunto. A quantidade de ordens possíveis de n elementos distintos é n!.','Pₙ=n!.','Uma permutação simples ordena todos os elementos ou apenas uma parte?','Todos os elementos distintos do conjunto.',k=>Q(`Uma prateleira recebe ${k+3} livros diferentes. De quantas formas eles podem ser ordenados?`,fact(k+3),`São ${k+3}! = ${fact(k+3)} ordens.`),'permutação simples'),
 L('Permutação com repetição','Quando há elementos indistinguíveis, a contagem n! repete configurações iguais. Divida pelos fatoriais das quantidades repetidas.','P=n!/(a!b!…).','Por que dividimos pelos fatoriais das repetições?','Para retirar ordens que são indistinguíveis entre si.',k=>{const words=['ANA','OVO','ATA','EVE'];return Q(`Quantos anagramas distintos podem ser formados com as letras de ${words[k]}?`,3,'Há 3 letras, sendo 2 iguais: 3!/2!=3.');},'permutação repetição'),
 L('Permutação circular','Em uma roda sem posições numeradas, configurações obtidas apenas por rotação são equivalentes. Fixar um elemento remove essa repetição. Imagens espelhadas ainda são diferentes na convenção usual.','Permutações circulares de n distintos: (n−1)!.','Por que a fórmula circular usa (n−1)!?','Fixamos um elemento para não contar novamente as rotações da mesma roda.',k=>Q(`${k+4} amigos sentam em uma mesa redonda. Considerando rotações equivalentes, quantas disposições existem?`,fact(k+3),`Fixe um amigo e permute os demais: (${k+4}−1)! = ${fact(k+3)}.`),'permutação circular'),
 L('Combinação','Uma combinação escolhe elementos sem considerar sua ordem. Escolher Ana e Bia forma o mesmo grupo que escolher Bia e Ana.','C(n,p)=n!/[p!(n−p)!].','Se a ordem da escolha não importa, usamos arranjo ou combinação?','Combinação.',k=>Q(`Uma comissão de 2 pessoas será escolhida entre ${k+4} candidatos. Quantas comissões diferentes existem?`,(k+4)*(k+3)/2,`C(${k+4},2)=${k+4}×${k+3}/2=${(k+4)*(k+3)/2}.`),'combinação'),
 L('Arranjo','Arranjos escolhem parte dos elementos e levam em conta a ordem. Trocar o primeiro e o segundo lugar muda o resultado.','A(n,p)=n!/(n−p)!.','O que diferencia arranjo de combinação?','No arranjo, a ordem dos escolhidos importa.',k=>Q(`Numa competição com ${k+4} participantes, quantos pódios de primeiro e segundo lugar são possíveis sem empate?`,(k+4)*(k+3),`Há ${k+4} opções para primeiro e ${k+3} para segundo.`),'arranjo'),
 L('Probabilidade','No modelo equiprovável, a probabilidade é a razão entre casos favoráveis e casos possíveis. Verifique se os resultados têm a mesma chance antes de usar essa contagem.','P(A)=casos favoráveis/casos possíveis, no modelo equiprovável.','A fórmula favoráveis/possíveis pressupõe o quê?','Que os resultados elementares sejam equiprováveis.',k=>Q(`Uma urna contém ${k+2} bolas azuis e ${k+2} vermelhas, todas com a mesma chance de sair. Qual é a probabilidade de retirar uma azul?`,'1/2','As bolas azuis correspondem à metade do total.',['1/3','1/4','2/3','1']),'probabilidade'),
 L('Soma e multiplicação de probabilidades','Para união, some as probabilidades e subtraia a interseção. Para interseção, use probabilidade condicional; em eventos independentes, multiplique as probabilidades individuais.','P(A∪B)=P(A)+P(B)−P(A∩B); P(A∩B)=P(A)P(B|A).','Quando P(A∩B)=P(A)P(B)?','Quando A e B são independentes.',k=>Q(`Uma moeda equilibrada é lançada duas vezes, de forma independente. Qual é a probabilidade de ${['duas caras','duas coroas','cara e depois coroa','coroa e depois cara'][k]}?`,'1/4','Cada resultado especificado tem probabilidade 1/2 × 1/2 = 1/4.',['1/2','1/3','3/4','1']),'probabilidade união interseção')]],
 ['Estatística','Descreva conjuntos de dados e interprete medidas de tendência central. Compare média, mediana e moda antes de escolher a medida mais útil.','statistics',[
 L('Introdução à estatística','Estatística organiza, resume e interpreta dados. População é o grupo de interesse; amostra é a parte observada. Conclusões dependem de como os dados foram coletados.','Uma amostra precisa representar a população para sustentar generalizações.','Qual a diferença entre população e amostra?','População é o grupo de interesse; amostra é a parte dele que foi observada.',k=>Q(`Uma escola tem ${200+100*k} alunos. Uma pesquisa entrevista apenas 30 deles. Quantos alunos compõem a amostra?`,30,'A amostra é o grupo entrevistado: 30 alunos.'),'introdução estatística'),
 L('Média aritmética e ponderada','A média simples soma os valores e divide pela quantidade. A ponderada atribui pesos, que representam participações ou importância de cada valor.','Média ponderada=Σ(xᵢpᵢ)/Σpᵢ.','Qual é o denominador na média ponderada?','A soma dos pesos.',k=>Q(`Um estudante tirou ${k+4} em uma prova de peso 1 e ${k+6} em outra de peso 3. Qual é sua média ponderada?`,n(k+5.5),`[${k+4}+3×${k+6}]/4=${n(k+5.5)}.`,[n(k+5),n(k+6),n(k+4.5),n(k+6.5)]),'média aritmética ponderada',['math.m18.t03']),
 L('Mediana e moda','Ordene os dados para encontrar a mediana. Ela ocupa a posição central ou é a média dos dois valores centrais. A moda é o valor mais frequente, e pode não ser única.','Com n ímpar, a mediana está na posição (n+1)/2.','É preciso ordenar os dados para calcular a mediana?','Sim.',k=>Q(`As idades registradas foram ${k+10}, ${k+11}, ${k+12}, ${k+12} e ${k+15}. Qual é a mediana?`,k+12,`Os cinco valores já estão ordenados. A mediana é o terceiro: ${k+12}.`),'mediana moda',['math.m18.t04'])]],
 ['Geometria analítica','Use coordenadas e equações para estudar figuras. Conecte a interpretação algébrica a distâncias, áreas, retas e circunferências.','geometry',[
 L('Introdução à geometria analítica','O plano cartesiano usa dois eixos perpendiculares. Cada ponto é um par ordenado, e distâncias entre pontos podem ser calculadas a partir de Pitágoras.','d=√[(x₂−x₁)²+(y₂−y₁)²].','Como é representado um ponto do plano cartesiano?','Por um par ordenado (x,y).',k=>Q(`Um mapa usa os pontos A=(0,0) e B=(${3*(k+1)},${4*(k+1)}). Qual é a distância entre eles?`,5*(k+1),'Aplique a fórmula da distância; as diferenças formam um triângulo 3-4-5 ampliado.'),'geometria analítica'),
 L('Áreas de figuras planas por coordenadas','As coordenadas permitem obter bases, alturas e áreas. Para triângulos, uma base horizontal simplifica a leitura da altura; o determinante também fornece a área.','Área do triângulo=|x₁(y₂−y₃)+x₂(y₃−y₁)+x₃(y₁−y₂)|/2.','Por que usamos valor absoluto no cálculo de área por determinante?','Porque a área é não negativa e a ordem dos pontos pode mudar o sinal.',k=>Q(`Um triângulo tem vértices (0,0), (${2*(k+2)},0) e (0,3). Qual é a área?`,3*(k+2),`Base=${2*(k+2)} e altura=3. Área=base×altura/2=${3*(k+2)}.`),'área triângulo coordenadas'),
 L('Equações da reta','Uma reta não vertical pode ser descrita por y=mx+b. O coeficiente m representa a variação vertical por unidade horizontal; retas verticais têm equação x=c.','y−y₀=m(x−x₀).','Toda reta pode ser escrita como y=mx+b?','Não. Retas verticais têm equação x=c.',k=>Q(`Uma reta tem inclinação 2 e passa pelo ponto (0,${k+3}). Qual é sua equação?`,`y = 2x + ${k+3}`,'Na forma y=mx+b, m=2 e b é a coordenada y quando x=0.',[`y = ${k+3}x + 2`,`y = 2x − ${k+3}`,`x = ${k+3}`,`y = x + ${k+3}`]),'equação reta',['math.m17.t04']),
 L('Posições entre retas','No plano, retas podem coincidir, ser paralelas distintas ou se cruzar. Para retas não verticais, coeficientes angulares iguais indicam paralelismo ou coincidência.','Retas perpendiculares não verticais: m₁m₂=−1.','O que é preciso comparar além da inclinação para distinguir retas paralelas e coincidentes?','O termo independente, ou um ponto de cada reta.',k=>Q(`As retas y=3x+${k+1} e y=3x+${k+5} estão no mesmo plano. Qual é sua posição relativa?`,'Paralelas distintas','Têm a mesma inclinação e termos independentes diferentes.',['Coincidentes','Perpendiculares','Reversas','Concorrentes oblíquas']),'posições retas'),
 L('Equações da circunferência','Uma circunferência reúne pontos à mesma distância do centro. A equação reduzida permite ler centro e raio, prestando atenção aos sinais.','(x−a)²+(y−b)²=r².','Qual é o centro de (x−2)²+(y+3)²=25?','(2,−3).',k=>Q(`Um projeto usa a circunferência (x−1)²+(y−2)²=${(k+3)**2}. Qual é o raio?`,k+3,`O lado direito é r². Portanto r=√${(k+3)**2}=${k+3}.`),'equação circunferência',['math.m17.t07'])]],
 ['Pré-cálculo','Reúna as bases necessárias para iniciar Cálculo 1. Amplie o repertório com funções racionais, vetores, matrizes, séries e uma primeira ideia de limite e continuidade.','functions',[
 L('Funções compostas e inversas','Revise composição com atenção ao domínio. Para inverter, troque entrada e saída e resolva a equação, considerando se a função é bijetiva nos conjuntos escolhidos.','Domínio de f∘g: x no domínio de g com g(x) no domínio de f.','Qual cuidado adicional existe no domínio de uma função composta?','A saída de g precisa pertencer ao domínio de f.',k=>Q(`Uma conversão é dada por f(x)=${k+2}x+3. Qual é a expressão da inversa?`,`f⁻¹(x) = (x−3)/${k+2}`,`De y=${k+2}x+3, isole x=(y−3)/${k+2} e troque a variável de entrada.`,[`f⁻¹(x) = ${k+2}x−3`,`f⁻¹(x) = (x+3)/${k+2}`,`f⁻¹(x) = x/${k+2}+3`,`f⁻¹(x) = 1/(${k+2}x+3)`]),'função inversa'),
 L('Trigonometria para pré-cálculo','Revise radianos, identidades e gráficos periódicos. As transformações de seno e cosseno alteram amplitude, período e deslocamento sem mudar sua natureza periódica.','Período de sen(bx): 2π/|b|, para b≠0.','Graus e radianos podem ser misturados numa mesma conta sem conversão?','Não. Escolha a unidade e converta quando necessário.',k=>Q(`Uma oscilação é descrita por f(x)=sen(${k+2}x). Qual é seu período?`,['π','2π/3','π/2','2π/5'][k],`O período é 2π/|b|, com b=${k+2}.`,['2π','4π','π/3','5π']),'período função seno'),
 L('Números complexos','Os complexos têm forma a+bi, com i²=−1. Eles ampliam os reais e permitem resolver equações como x²+1=0. Some as partes reais e imaginárias separadamente.','(a+bi)+(c+di)=(a+c)+(b+d)i.','Quanto vale i²?','−1.',k=>Q(`Num cálculo, z=(${k+2}+2i)+(3+i). Qual é o resultado?`,`${k+5}+3i`,'Some as partes reais e as imaginárias separadamente.',[`${k+5}+2i`,`${k+2}+3i`,`${k+6}+3i`,`${k+5}−3i`]),'números complexos'),
 L('Funções racionais','Uma função racional é um quociente de polinômios. Zeros do denominador ficam fora do domínio, mesmo quando um fator pode ser cancelado para simplificar a expressão.','f(x)=p(x)/q(x), com q(x)≠0.','Cancelar um fator devolve ao domínio um valor antes proibido?','Não. A restrição da expressão original permanece.',k=>Q(`Um modelo usa f(x)=1/(x−${k+2}). Qual valor de x deve ser excluído do domínio real?`,k+2,`O denominador zera em x=${k+2}.`),'funções racionais'),
 L('Seções cônicas','Círculo, elipse, parábola e hipérbole podem ser obtidos por cortes de um cone. Suas equações refletem propriedades geométricas como focos e eixos.','Elipse centrada na origem: x²/a²+y²/b²=1, com a,b>0.','Qual cônica tem pontos cuja soma das distâncias a dois focos é constante?','A elipse.',k=>Q(`A equação de uma curva é x²/${(k+3)**2}+y²/4=1. Quanto mede o semieixo horizontal?`,k+3,`O denominador de x² é o quadrado do semieixo: a=${k+3}.`),'cônicas elipse'),
 L('Vetores','Um vetor descreve módulo, direção e sentido. Em coordenadas, some componentes correspondentes; o módulo é obtido pela raiz da soma dos quadrados.','(a,b)+(c,d)=(a+c,b+d).','Somar vetores em coordenadas significa fazer o quê?','Somar as componentes correspondentes.',k=>Q(`Um deslocamento u=(${k+1},2) é seguido por v=(3,4). Qual é o deslocamento resultante?`,`(${k+4},6)`,'Some as componentes horizontal e vertical.',[`(${k+4},2)`,`(${k+1},6)`,`(${k+3},6)`,`(${k+4},8)`]),'vetores'),
 L('Matrizes','Matrizes organizam valores em linhas e colunas. Somas exigem dimensões iguais; na multiplicação, o número de colunas da primeira precisa igualar o de linhas da segunda.','(m×n)(n×p) resulta em matriz m×p.','A multiplicação de matrizes é sempre comutativa?','Não. Em geral AB≠BA, e um dos produtos pode nem existir.',k=>Q(`Uma planilha matricial tem ${k+2} linhas e 3 colunas. Quantos elementos ela possui?`,3*(k+2),`Quantidade de elementos = linhas × colunas.`),'matrizes'),
 L('Probabilidade e análise combinatória','Revise contagem e probabilidade distinguindo ordem, reposição e independência. Sem reposição, a segunda escolha geralmente depende da primeira.','P(A∩B)=P(A)P(B|A).','Retiradas sem reposição são, em geral, independentes?','Não. A primeira retirada altera a composição disponível para a segunda.',k=>Q(`Uma equipe de 2 pessoas será escolhida entre ${k+5} candidatos, sem cargos diferentes. Quantas equipes existem?`,(k+5)*(k+4)/2,`A ordem não importa: C(${k+5},2)=${(k+5)*(k+4)/2}.`),'probabilidade análise combinatória'),
 L('Séries','Uma série é a soma dos termos de uma sequência. Uma série geométrica infinita converge quando o módulo da razão é menor que 1; caso contrário, essa fórmula de soma não se aplica.','Σ a₁qⁿ = a₁/(1−q), com n começando em 0 e |q|<1.','Quando uma série geométrica infinita tem soma a₁/(1−q)?','Quando |q|<1.',k=>Q(`Uma série geométrica infinita começa em ${k+1} e cada termo é metade do anterior. Qual é sua soma?`,2*(k+1),`S=a₁/(1−q)=${k+1}/(1−1/2)=${2*(k+1)}.`),'série geométrica infinita'),
 L('Limites e continuidade','Um limite descreve o comportamento da função quando a entrada se aproxima de um valor. Continuidade em a exige f(a) definida, limite existente e igualdade entre limite e valor.','Continuidade em a: lim(x→a)f(x)=f(a).','A existência de um limite obriga a função a estar definida naquele ponto?','Não. O limite depende dos valores próximos, não do valor isolado no ponto.',k=>Q(`Para acompanhar uma tendência, considere f(x)=2x+1. Qual é o limite de f(x) quando x se aproxima de ${k+2}?`,2*k+5,`Polinômios são contínuos: substitua x por ${k+2}, obtendo ${2*k+5}.`),'limites continuidade')]]
];
function uniqueOptions(correct,wrong){const values=[String(correct),...wrong];let fallback=0;while(new Set(values).size<5)values.push(String(100+fallback++));return [...new Set(values)].slice(0,5);}
export function createRoadmap(){const questions=[];const modules=groups.map(([title,description,videoTopic,lessons],mi)=>{const id=`roadmap.m${String(mi+1).padStart(2,'0')}`;return {id,order:mi+1,title,description,videoTopic,lessons:lessons.map((row,li)=>{const lid=id+`.l${String(li+1).padStart(2,'0')}`;const questionIds=[];for(let k=0;k<4;k++){const data=row.question(k),qid='equacao:'+lid+':'+(k+1),options=uniqueOptions(data.answer,data.wrong),shift=(mi+li+k)%5,ordered=options.slice(shift).concat(options.slice(0,shift));if(options.length!==5)throw new Error('Alternativas insuficientes: '+lid);const alternatives=ordered.map((text,i)=>({letter:'ABCDE'[i],text,file:null}));questions.push({id:qid,nativeId:qid,source:'equacao',level:mi===0?'EASY':'MEDIUM',levelOrigin:'curriculum',year:null,title:row.title,topic:title,statement:data.statement,format:'markdown',introduction:'',files:[],alternatives,answer:alternatives.find(a=>a.text===data.answer).letter,explanation:data.explanation,question:data.statement,dedupeKey:qid,learning:{moduleId:id,lessonId:lid}});questionIds.push(qid);}const example=questions[questions.length-4];return {id:lid,order:li+1,title:row.title,explanation:row.explanation,rule:row.rule,card:{id:lid,...row.card},videoTopic,videoTerms:row.videoTerms,legacyIds:row.legacyIds,questionIds,example:{question:example.statement,answer:example.alternatives.find(a=>a.letter===example.answer).text,explanation:example.explanation}};})};});return {roadmap:{schemaVersion:1,title:'Matemática antes de Cálculo 1',source:'Roadmap fornecido pelo usuário; conteúdo didático autoral do Equação.',reference:'https://pt.khanacademy.org/math/precalculus',modules},questions};}
